require_once __DIR__.'/core.php';require_once __DIR__.'/federation_lib.php';require_once __DIR__.'/maintenance.php';tt_require_login();$user=(string)$_SESSION['name'];$id=(int)$_SESSION['id'];$db=tt_db_open(true);try{tt_opportunistic_maintenance($db);tt_federation_tick($db);}catch(Throwable $e){}
